:- module(m__eu_dora_ict_risk_response_and_recovery_citations, [citation/2, implements/1]).
:- use_module(library(lists)).
:- use_module(library(iso_ext)).
:- use_module(library(between)).
:- use_module(library(dif)).

implements(Key) :-
    citation(Key, _).

citation(eu_reg_2022_2554_art_11_1, [label - 'Regulation (EU) 2022/2554 (DORA) Art 11(1) (ICT business continuity policy)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32022R2554', verbatim - 'financial entities shall put in place a comprehensive ICT business continuity policy']).
citation(eu_reg_2022_2554_art_11_2, [label - 'Regulation (EU) 2022/2554 (DORA) Art 11(2), lead words (implementation of the ICT business continuity policy through documented arrangements)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32022R2554', verbatim - 'Financial entities shall implement the ICT business continuity policy through dedicated, appropriate and documented arrangements, plans, procedures and mechanisms aiming to']).
citation(eu_reg_2022_2554_art_11_2_a, [label - 'Regulation (EU) 2022/2554 (DORA) Art 11(2)(a) (continuity of critical or important functions)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32022R2554', verbatim - 'ensure the continuity of the financial entity']).
citation(eu_reg_2022_2554_art_11_2_b, [label - 'Regulation (EU) 2022/2554 (DORA) Art 11(2)(b) (response to and resolution of ICT-related incidents)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32022R2554', verbatim - 'quickly, appropriately and effectively respond to, and resolve, all ICT-related incidents in a way that limits damage and prioritises the resumption of activities and recovery actions']).
citation(eu_reg_2022_2554_art_11_2_c, [label - 'Regulation (EU) 2022/2554 (DORA) Art 11(2)(c) (activation of containment plans without delay)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32022R2554', verbatim - 'activate, without delay, dedicated plans that enable containment measures, processes and technologies suited to each type of ICT-related incident and prevent further damage']).
citation(eu_reg_2022_2554_art_11_2_d, [label - 'Regulation (EU) 2022/2554 (DORA) Art 11(2)(d) (estimation of preliminary impacts, damages and losses)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32022R2554', verbatim - 'estimate preliminary impacts, damages and losses']).
citation(eu_reg_2022_2554_art_11_2_e, [label - 'Regulation (EU) 2022/2554 (DORA) Art 11(2)(e) (communication and crisis management actions)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32022R2554', verbatim - 'set out communication and crisis management actions that ensure that updated information is transmitted to all relevant internal staff and external stakeholders in accordance with Article 14, and report to the competent authorities in accordance with Article 19']).
citation(eu_reg_2022_2554_art_11_3, [label - 'Regulation (EU) 2022/2554 (DORA) Art 11(3) (ICT response and recovery plans and their independent internal audit review, other than microenterprises)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32022R2554', verbatim - 'financial entities shall implement associated ICT response and recovery plans which, in the case of financial entities other than microenterprises, shall be subject to independent internal audit reviews']).
citation(eu_reg_2022_2554_art_11_4, [label - 'Regulation (EU) 2022/2554 (DORA) Art 11(4) (ICT business continuity plans)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32022R2554', verbatim - 'Financial entities shall put in place, maintain and periodically test appropriate ICT business continuity plans']).
citation(eu_reg_2022_2554_art_11_5, [label - 'Regulation (EU) 2022/2554 (DORA) Art 11(5) (business impact analysis and alignment of ICT assets and services with it)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32022R2554', verbatim - 'financial entities shall conduct a business impact analysis (BIA) of their exposures to severe business disruptions']).
citation(eu_reg_2022_2554_art_11_6, [label - 'Regulation (EU) 2022/2554 (DORA) Art 11(6) (testing and review; second subparagraph: cyber-attack and switchover scenarios, other than microenterprises; third subparagraph: regular review of the policy and plans)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32022R2554', verbatim - 'Financial entities shall regularly review their ICT business continuity policy and ICT response and recovery plans']).
citation(eu_reg_2022_2554_art_11_6_a, [label - 'Regulation (EU) 2022/2554 (DORA) Art 11(6), first subparagraph, point (a) (testing of the plans at least yearly and on substantive changes)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32022R2554', verbatim - 'test the ICT business continuity plans and the ICT response and recovery plans in relation to ICT systems supporting all functions at least yearly']).
citation(eu_reg_2022_2554_art_11_6_b, [label - 'Regulation (EU) 2022/2554 (DORA) Art 11(6), first subparagraph, point (b) (testing of the crisis communication plans)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32022R2554', verbatim - 'test the crisis communication plans established in accordance with Article 14']).
citation(eu_reg_2022_2554_art_11_7, [label - 'Regulation (EU) 2022/2554 (DORA) Art 11(7) (crisis management function, other than microenterprises)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32022R2554', verbatim - 'Financial entities, other than microenterprises, shall have a crisis management function']).
citation(eu_reg_2022_2554_art_11_8, [label - 'Regulation (EU) 2022/2554 (DORA) Art 11(8) (records of activities when the plans are activated)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32022R2554', verbatim - 'Financial entities shall keep readily accessible records of activities before and during disruption events']).
citation(eu_reg_2022_2554_art_11_9, [label - 'Regulation (EU) 2022/2554 (DORA) Art 11(9) (central securities depositories: results of ICT business continuity tests to the competent authorities)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32022R2554', verbatim - 'Central securities depositories shall provide the competent authorities with copies of the results of the ICT business continuity tests, or of similar exercises']).
citation(eu_reg_2022_2554_art_11_10, [label - 'Regulation (EU) 2022/2554 (DORA) Art 11(10) (estimate of aggregated annual costs and losses on request, other than microenterprises)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32022R2554', verbatim - 'Financial entities, other than microenterprises, shall report to the competent authorities, upon their request, an estimation of aggregated annual costs and losses caused by major ICT-related incidents']).
citation(eu_reg_2022_2554_art_12_1, [label - 'Regulation (EU) 2022/2554 (DORA) Art 12(1), lead words (development and documentation of backup and restoration procedures)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32022R2554', verbatim - 'For the purpose of ensuring the restoration of ICT systems and data with minimum downtime, limited disruption and loss']).
citation(eu_reg_2022_2554_art_12_1_a, [label - 'Regulation (EU) 2022/2554 (DORA) Art 12(1)(a) (backup policies and procedures)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32022R2554', verbatim - 'backup policies and procedures specifying the scope of the data that is subject to the backup and the minimum frequency of the backup']).
citation(eu_reg_2022_2554_art_12_1_b, [label - 'Regulation (EU) 2022/2554 (DORA) Art 12(1)(b) (restoration and recovery procedures and methods)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32022R2554', verbatim - 'restoration and recovery procedures and methods']).
citation(eu_reg_2022_2554_art_12_2, [label - 'Regulation (EU) 2022/2554 (DORA) Art 12(2) (backup systems, their secure activation and periodic testing)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32022R2554', verbatim - 'Financial entities shall set up backup systems that can be activated in accordance with the backup policies and procedures']).
citation(eu_reg_2022_2554_art_12_3, [label - 'Regulation (EU) 2022/2554 (DORA) Art 12(3) (segregated restoration systems; central counterparties; data reporting service providers)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32022R2554', verbatim - 'When restoring backup data using own systems, financial entities shall use ICT systems that are physically and logically segregated from the source ICT system']).
citation(eu_reg_2022_2554_art_12_4, [label - 'Regulation (EU) 2022/2554 (DORA) Art 12(4) (redundant ICT capacities, other than microenterprises; assessment of the need by microenterprises)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32022R2554', verbatim - 'Financial entities, other than microenterprises, shall maintain redundant ICT capacities']).
citation(eu_reg_2022_2554_art_12_5, [label - 'Regulation (EU) 2022/2554 (DORA) Art 12(5), lead words (central securities depositories: secondary processing site)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32022R2554', verbatim - 'Central securities depositories shall maintain at least one secondary processing site']).
citation(eu_reg_2022_2554_art_12_5_a, [label - 'Regulation (EU) 2022/2554 (DORA) Art 12(5)(a) (secondary processing site at a geographical distance)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32022R2554', verbatim - 'located at a geographical distance from the primary processing site']).
citation(eu_reg_2022_2554_art_12_5_b, [label - 'Regulation (EU) 2022/2554 (DORA) Art 12(5)(b) (secondary processing site capable of ensuring continuity)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32022R2554', verbatim - 'capable of ensuring the continuity of critical or important functions identically to the primary site']).
citation(eu_reg_2022_2554_art_12_5_c, [label - 'Regulation (EU) 2022/2554 (DORA) Art 12(5)(c) (secondary processing site immediately accessible to staff)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32022R2554', verbatim - 'immediately accessible to the financial entity']).
citation(eu_reg_2022_2554_art_12_6, [label - 'Regulation (EU) 2022/2554 (DORA) Art 12(6) (recovery time and recovery point objectives)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32022R2554', verbatim - 'In determining the recovery time and recovery point objectives for each function']).
citation(eu_reg_2022_2554_art_12_7, [label - 'Regulation (EU) 2022/2554 (DORA) Art 12(7) (data integrity checks when recovering; consistency checks when reconstructing data from external stakeholders)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32022R2554', verbatim - 'When recovering from an ICT-related incident, financial entities shall perform necessary checks']).
citation(eu_reg_2022_2554_art_16_1, [label - 'Regulation (EU) 2022/2554 (DORA) Art 16(1), first subparagraph (entities to which Articles 5 to 15 do not apply)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32022R2554', verbatim - 'Articles 5 to 15 of this Regulation shall not apply to small and non-interconnected investment firms']).
citation(eu_reg_2022_2554_art_3_60, [label - 'Regulation (EU) 2022/2554 (DORA) Art 3(60) definition of microenterprise (not pinned; the caller states the size class, reading (4))', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32022R2554']).
